ROOT=pathlib.Path(__file__).parent
rows=[]
LESSONS={'lin':'Linear functions and slope','eq':'Linear equations and inequalities','sys':'Systems of equations','quad':'Quadratic equations and functions','poly':'Polynomials and factoring','exp':'Exponents and radicals','rat':'Rational expressions and equations','abs':'Absolute value','pct':'Ratios, percentages and unit conversion','stat':'Statistics and data analysis','prob':'Probability','tri':'Triangles and trigonometry','cir':'Circles','vol':'Volume and surface area','fun':'Functions'}
def a(p,m,n,page,t,stem,choices,correct,explanation,fig=None,check=None):
 rows.append(dict(ref=f'P{p}-{m}-{n:02}',paper=p,module=m,number=n,page=page,topic=LESSONS[t],stem=stem,choices=choices,correct=correct,explanation=explanation,figure_crop=fig,check=check))
