def repeat(ref,p,m,n,page):
 old=next(r for r in rows if r['ref']==ref)
 import copy
 new=copy.deepcopy(old);new.update(ref=f'P{p}-{m}-{n:02}',paper=p,module=m,number=n,page=page,duplicate_of=ref,figure_crop=None);rows.append(new)
