# Paper 2, baseline; separate supplied key cross-checked.
a(2,'M1',1,42,'lin','The function f(x)=100x+7. What is f(5)?',['112','135','500','507'],'D','100(5)+7=507.',check='100*5+7 == 507')
a(2,'M1',2,42,'stat','Kayla recorded heights of 25 neighbors. The histogram has frequencies 4, 6, 5, 8, 2 for the intervals [51,53), [53,55), [55,57), [57,59), [59,61) inches. How many people were at least 51 inches but less than 55 inches tall?',None,'10','Add the first two histogram frequencies: 4+6=10.',[105,850,480,1130])
a(2,'M1',3,42,'poly','Which expression is equivalent to 32x² + 32?',['32(x² + 1)','32(x² + 32)','32(32x² + 1)',r'\(32(x^2+\frac1{32})\)'],'A','Factor the common factor 32: 32(x²+1).')
a(2,'M1',4,43,'eq','If 2(x − 10) = (2)(80), what is x − 10?',['8','16','80','160'],'C','Divide both sides by 2 to obtain x−10=80.')
a(2,'M1',5,43,'tri','Triangle ABC is dilated by a scale factor of 3 to form triangle A′B′C′. If AB=21, what is A′B′?',['3','7','24','63'],'D','Corresponding lengths are multiplied by 3: 21×3=63.',[110,495,570,740])
a(2,'M1',6,43,'quad','What is an x-intercept of y = x² − 81?',['(1,0)','(9,0)','(18,0)','(81,0)'],'B','Set y=0: x²=81 gives x=±9. The listed intercept is (9,0).')
a(2,'M1',7,44,'lin','A store sells two shampoo sizes. Sales totaled $910.53 last month. The equation 4.59x + 6.09y = 910.53 models sales, with x smaller and y larger bottles. What is the price, in dollars, of each smaller bottle?',None,'4.59','The coefficient of x is the price per smaller bottle: $4.59.')
repeat('P1-M1-08',2,'M1',8,44)
a(2,'M1',9,44,'lin','Line k passes through (0,−9) and (1,−5). Which equation defines k?',[r'\(y=\frac14x-9\)',r'\(y=-x+\frac14\)','y = 4x − 9','y = −x + 4'],'C','Slope=(−5+9)/(1−0)=4 and the y-intercept is −9.')
a(2,'M1',10,45,'stat','Which equation is the most appropriate linear model for the scatterplot?',['y = 0.2 + 2.28x','y = 0.2 − 2.28x','y = 2.28 + 0.2x','y = 2.28 − 0.2x'],'A','The positive trend rises about 2.28 units per x-unit, with an intercept near zero. The remaining slopes have the wrong sign or size.',[140,150,545,550])
a(2,'M1',11,45,'quad','The function g(x)=(24−2x)(10+2x). For what x does g reach its maximum?',['3.5','7','8.5','17'],'A','Expand: g(x)=−4x²+28x+240. The vertex is at x=−28/(2×−4)=3.5.')
a(2,'M1',12,46,'exp',r'An exponential function is \(f(x)=k2^x\), where k>0. If f(−1)=8 and f(2)=64, what is k?',['8','9','15','16'],'D','f(−1)=k/2=8 gives k=16. This also gives f(2)=16×4=64.')
a(2,'M1',13,46,'vol','A right rectangular pyramid has base length 27 cm, base width 7 cm, and height 5 cm. What is its volume, in cm³?',None,'315','V=(1/3)×27×7×5=315.',check='27*7*5/3 == 315')
a(2,'M1',14,46,'eq',r'For an object of mass 66 kg, \(66=\frac{2K}{v^2}\), where K and v are positive. Which equation expresses speed v in terms of kinetic energy K?',[r'\(v=\frac{2K}{66^2}\)',r'\(v=\frac{66^2}{2K}\)',r'\(v=\sqrt{\frac{66}{2K}}\)',r'\(v=\sqrt{\frac{2K}{66}}\)'],'D','Rearrange to v²=2K/66 and take the positive square root.')
a(2,'M1',15,46,'rat',r'If \(\frac jk=95\) and \(\frac{36j}{12xk}=95\), what is x?',[r'\(\frac{12}{95}\)',r'\(\frac13\)','3','36'],'C','Substitute j/k=95 to get (3/x)95=95, so x=3.')
a(2,'M1',16,47,'sys','Which point solves y ≥ x + 15 and y ≤ −5x − 15?',['(−6,13)','(−6,8)','(−4,13)','(−4,8)'],'A','At (−6,13), 13≥9 and 13≤15. The other listed points fail at least one inequality.')
a(2,'M1',17,47,'lin','A plumber charges $111 for the first hour, $50 for each additional hour, and $z for parts. Which equation gives total cost y for x hours, x ≥ 1?',['y = 50x + z','y = 50x + z + 61','y = 111x + z','y = 111x + 50z + 61'],'B','y=111+50(x−1)+z=50x+z+61.')
a(2,'M1',18,47,'tri','In the right triangle shown, A=C=45°, B=90°, and hypotenuse AC=x=8. What is sin A?',[r'\(\frac1{\sqrt3}\)',r'\(\frac1{\sqrt2}\)','1',r'\(\sqrt2\)'],'B','sin A=sin45°=√2/2=1/√2.',[100,1120,310,1350])
a(2,'M1',19,48,'eq','The shaded region represents −19y < c, where c is constant. What is c?',['114','6','−6','−114'],'A','The shading is above dashed y=−6, hence y>−6. Multiplying by −19 gives −19y<114, so c=114.',[140,145,535,555])
a(2,'M1',20,48,'sys','A solution of y=x−1 and y=27(x−1)²−28 is (x,y). What is one possible value of x−1?',['−2',r'\(-\frac{28}{27}\)','−1',r'\(-\frac1{27}\)'],'C','Let u=x−1. Then 27u²−u−28=(u+1)(27u−28)=0. The listed root is u=−1.')
a(2,'M1',21,49,'sys',r'The system is \(10x+14y=6y+5\) and \(ty=\frac13+5x\). If there is no solution, what is t?',None,'-4','The first equation is y=−(5/4)x+5/8. The second has slope 5/t when t≠0. Equal slopes give t=−4, with different intercepts 5/8 and −1/12. At t=0 the equations intersect.')
a(2,'M1',22,49,'abs','What is the sum of the solutions of 4|x+3| − 2 = 22?',None,'-6','|x+3|=6 gives x=3 or −9. Their sum is −6.')
# Paper 2, easy second module.
a(2,'M2E',1,49,'stat','The scatterplot relates age and daily internet time for six people. How many hours per day does the 70-year-old person spend on the internet?',['3','5','7','8'],'A','The plotted point at age 70 has y=3 hours.',[110,880,560,1340])
a(2,'M2E',2,50,'eq','What is the solution of x + 31 = 62?',['2','31','62','93'],'B','Subtract 31: x=31.')
a(2,'M2E',3,50,'prob','In a litter of 5 kittens, 2 are striped. If one kitten is selected at random, what is the probability it is striped?',[r'\(\frac15\)',r'\(\frac25\)',r'\(\frac35\)',r'\(\frac55\)'],'B','There are 2 favorable outcomes among 5 equally likely kittens, so the probability is 2/5.')
a(2,'M2E',4,50,'exp',r'What is the y-intercept of \(y=(\frac2{17})^{x+1}\)?',['(2,17)','(0,17)','(0,2)',r'\((0,\frac2{17})\)'],'D','At x=0, y=(2/17)¹=2/17. The intercept is (0,2/17); the separate key loses the fraction bar.')
a(2,'M2E',5,51,'sys',r'The system \(y=\frac{24}{x}\) and y=24x is graphed as shown. Which ordered pair is a solution?',['(0,0)','(0,24)','(1,24)','(24,24)'],'C','Equating gives x²=1. Of the listed pairs, (1,24) satisfies both.',[140,145,535,545])
a(2,'M2E',6,51,'pct','A pigeon flies at 16 meters per second. How many meters does it fly in 3 seconds?',['48','19','16','13'],'A','Distance=rate×time=16×3=48 meters.')
a(2,'M2E',7,51,'eq','The equation x+y=92 gives the numbers of marble queen pothos stems x and snow queen pothos stems y propagated by a nursery. If y=32, how many marble queen stems are propagated?',['92','60','32','28'],'B','x=92−32=60.')
a(2,'M2E',8,52,'eq','A shipment of 5-pound and 10-pound boxes weighs 330 pounds. There are fifteen 10-pound boxes. How many 5-pound boxes are there?',['5','10','15','36'],'D','5x+10(15)=330 gives x=180/5=36.')
a(2,'M2E',9,52,'poly','Which expression is equivalent to 14x² − 5x²?',['−70x²','9x²','19x²','38x²'],'B','Combine like terms: (14−5)x²=9x².')
a(2,'M2E',10,52,'tri','In triangle ABC, angle A=36° and angle B=90°. What is angle C, in degrees?',['36','54','90','180'],'B','The angle sum gives C=180−36−90=54°.')
a(2,'M2E',11,52,'eq','A shopper has $15. Dog food costs $1.73 per can and treats cost $2.22 per bag. Which inequality relates the numbers c of cans and t of treat bags the shopper can buy?',['1.73c + 2.22t ≤ 15','1.73c + 2.22t ≥ 15','2.22c + 1.73t ≤ 15','2.22c + 1.73t ≥ 15'],'A','Total cost is 1.73c+2.22t and must be at most the $15 budget.')
a(2,'M2E',12,52,'pct','Out of 500 attempts, 55% were successful. How many attempts were successful?',None,'275','0.55×500=275.')
a(2,'M2E',13,52,'fun','The function f(x)=x²+x+53. What is f(2)?',None,'59','2²+2+53=59.')
a(2,'M2E',14,53,'exp',r'For a>0, \(y=3100a^x\) predicts the number of bacteria x hours after the initial measurement. What was the predicted initial number?',None,'3100','At x=0 the factor a⁰=1, so the initial value is 3100.')
a(2,'M2E',15,53,'tri','Triangle R has area 40 cm². Square S has side length 4 cm. What is their total area, in cm²?',['22','24','44','56'],'D','The square has area 4²=16. Total area=40+16=56.')
a(2,'M2E',16,53,'sys','The solution of 3x − 3y = 9 and −8y = 32 is (x,y). What is x?',None,'-1','y=−4; then 3x+12=9, giving x=−1.')
a(2,'M2E',17,53,'poly','What is an x-intercept of y=(x+7)(x−9)(x+12)?',['(3,0)','(0,7)','(9,0)','(0,12)'],'C','The roots are −7, 9, and −12. The listed x-intercept is (9,0).')
a(2,'M2E',18,54,'lin','A linear function f has the pairs (0,7), (1,13), (2,19). Which equation could define f?',['f(x) = 7x + 6','f(x) = 6x + 7','f(x) = x + 7','f(x) = 6x'],'B','The slope is 6 and f(0)=7, so f(x)=6x+7.')
a(2,'M2E',19,54,'pct','A dealership has only sedans, SUVs, and minivans. On Monday, 20% were sedans and 50% were SUVs. If there were 22 sedans, how many minivans were for sale?',None,'33','Total vehicles=22/0.20=110. Minivans are the remaining 30%, giving 0.30×110=33.')
a(2,'M2E',20,54,'quad','How many distinct real solutions does x²=−9 have?',['Exactly one','Exactly two','Infinitely many','Zero'],'D','The square of any real number is nonnegative. Therefore there are no real solutions.')
a(2,'M2E',21,54,'cir','A circle has equation (x−17)²+(y−k)²=36. Which gives its center and radius?',['Center (17,k), radius 6','Center (k,17), radius 6','Center (17,k), radius 36','Center (k,17), radius 36'],'A','Compare with (x−h)²+(y−k)²=r²: center (17,k), radius √36=6.')
a(2,'M2E',22,55,'lin','Line k passes through (3,0) and (0,5). Which is an equation of k?',['5x + 3y = 15','3x + 5y = 15','5x − 3y = 15','3x − 5y = 15'],'A','The intercept form x/3+y/5=1 becomes 5x+3y=15.')
# Paper 2, hard second module.
a(2,'M2H',1,55,'tri','In the figure, lines ℓ and k are parallel and transversal t intersects both. If x > 120, which statement must be true?',['y < 60','y > 60','x + y < 180','x + y > 180'],'A','The marked angles satisfy x+y=180. Thus x>120 implies y<60.',[110,680,425,1000])
a(2,'M2H',2,56,'lin','Water draining from garden roofs has the pairs (roof area x in square feet, water f(x) in gallons): (1040,2496), (1560,3744), (2080,4992). Which equation could define f?',['f(x) = 0.6x','f(x) = 2.4x','f(x) = 1248.0x','f(x) = 2496.0x'],'B','For all three pairs f(x)/x=2.4. Thus f(x)=2.4x.')
a(2,'M2H',3,56,'eq','If 13x + 325 = a(x + 25) has infinitely many solutions, what is a?',None,'13','The two sides must be identical. This requires a=13 and 25a=325, which agree.')
a(2,'M2H',4,56,'sys',r'The solution of \(y=-\frac1{11}x\) and \(y=\frac14x\) is (x,y). What is x?',['−11','−7','0','4'],'C','Both lines pass through the origin and have different slopes, so their only intersection has x=0.')
a(2,'M2H',5,56,'eq','An organization sells fundraiser tickets at $50 each. Expenses are $600 for the venue and $18 per person for food. What minimum number of tickets must be sold to earn at least $1,500 after expenses?',['30','42','47','66'],'D','50n−18n−600≥1500 gives n≥2100/32=65.625. The least integer is 66.')
a(2,'M2H',6,57,'fun',r'For \(f(x)=\frac{a-15}{x}+5\), the graph is translated 3 units down and 2 units right to produce g. Which equation defines g?',[r'\(g(x)=\frac{a-15}{x+2}+2\)',r'\(g(x)=\frac{a-15}{x-2}+2\)',r'\(g(x)=\frac{a-18}{x+2}+5\)',r'\(g(x)=\frac{a-18}{x-2}+5\)'],'B','Right 2 replaces x with x−2. Down 3 subtracts 3: g(x)=f(x−2)−3=(a−15)/(x−2)+2.')
a(2,'M2H',7,57,'stat','The scatterplot shows 9 data points and a line of best fit. For how many points does the line predict a y-value less than the actual y-value?',['9','6','3','0'],'C','Count points above the line. They occur at x=4, x=5, and x=9: three points.',[140,590,540,1010])
a(2,'M2H',8,57,'lin','Line p is 2y + 18x = 11. Line r is perpendicular to p. What is the slope of r?',['9',r'\(\frac19\)',r'\(-\frac19\)','−9'],'B','Line p is y=−9x+11/2, so its slope is −9. The perpendicular slope is 1/9. The supplied key incorrectly prints 1/1991.')
repeat('P2-M2E-04',2,'M2H',9,58)
a(2,'M2H',10,58,'exp',r'A liquid has approximate temperature \(g(t)=294+(364-294)(2.72)^{-0.104t}\) kelvins t minutes after placement on a table. What was its temperature at placement?',None,'364','At t=0, the exponential factor is 1. Thus g(0)=294+70=364.')
a(2,'M2H',11,58,'eq',r'Hannah saves \(\frac15\) of monthly salary h and Wyatt saves \(\frac27\) of monthly salary w. Together they save $3,160 each month. Which equation relates h and w?',['h + w = 3160','h + 2w = 3160','10h + 7w = 110600','7h + 10w = 110600'],'D','h/5+2w/7=3160. Multiply by 35 to obtain 7h+10w=110600.')
a(2,'M2H',12,58,'exp',r'The function \(f(x)=\sqrt{7x+6}\). If f(a)=−7a, what is a?',[r'\(-\frac67\)',r'\(-\frac27\)',r'\(\frac27\)',r'\(\frac37\)'],'B','The square root is nonnegative, so a≤0. Squaring gives 49a²−7a−6=0, with roots −2/7 and 3/7. Only −2/7 satisfies the original equation (both sides then equal 2).')
repeat('P2-M2E-19',2,'M2H',13,58)
a(2,'M2H',14,59,'quad','The equation 4x² + 14 = 32x + r has exactly one real solution. What is r?',None,'-50','Rewrite as 4x²−32x+14−r=0. Discriminant 1024−16(14−r)=800+16r=0 gives r=−50.')
a(2,'M2H',15,59,'tri','The right triangle shown has acute angles r° and s°. If 3r > 11s, which value must be greatest?',[r'\(\sin r^\circ\)',r'\(\cos r^\circ\)',r'\(\frac{\sin r^\circ}{\sin s^\circ}\)',r'\(\frac{\sin r^\circ}{\cos s^\circ}\)'],'C','r+s=90 and 3r>11s imply r>s. Therefore sin r/sin s>1, while sin r and cos r are below 1 and sin r/cos s=1.',[135,320,500,635])
a(2,'M2H',16,59,'stat','A researcher randomly selected 127 gamers from Sweden (25), South Korea (49), and the United States (53), then recorded melatonin levels and gaming time over 4 weeks. Which aspect prevents generalization to all gamers?',['The melatonin levels were not measured over a long enough period.','The number selected from each country is different.','The number of selected gamers is too small.','The gamers were not selected at random from all gamers.'],'D','The sample covers gamers in three countries rather than a random sample from all gamers worldwide. This limits the population to which results can be generalized.')
a(2,'M2H',17,60,'tri',r'The line segment shown is one leg of a right triangle. Its endpoints are (−7,5) and (2,11). The triangle has area \(42\sqrt{13}\) square units. What is the length of the other leg?',None,'28','The shown leg has length √(9²+6²)=√117=3√13. From (1/2)(3√13)b=42√13, the other leg b=28.',[135,145,550,555])
a(2,'M2H',18,60,'poly',r'The expression \(-12(5x-3)^2+6(5x-4)^2\) equals \(\frac a6x^2+\frac b6x+\frac c6\). What is a+b+c?',['−252','−126','−42','−7'],'A','At x=1, the expression is −12(2²)+6(1²)=−42=(a+b+c)/6. Therefore the sum is −252.')
a(2,'M2H',19,61,'lin','The graph of the linear function y=g(x)−17 is shown. If a and b are positive constants, which equation could define g?',['g(x) = −ax + b','g(x) = ax − b','g(x) = ax + b','g(x) = −ax − b'],'C','The shown line has positive slope and y-intercept −7. Adding 17 gives g a positive slope and intercept 10, hence g(x)=ax+b.',[120,115,550,545])
a(2,'M2H',20,61,'cir','A circle has center G and radius 238 mm. From external point H, HM and HN are tangent at M and N. The perimeter of quadrilateral GMHN is 4,508 mm. What is GH, in millimeters?',['238','2002','2016','2030'],'D','HM=HN, so 2(238)+2HM=4508 gives HM=2016. Radius GM is perpendicular to HM. GH=√(238²+2016²)=2030.',check='238**2+2016**2 == 2030**2')
a(2,'M2H',21,61,'poly','h(x)=a(x+43)(x+r)(x+s), where a, r, s are positive and the graph has exactly three x-intercepts. If h(0)=p, which must be true?',['p < 43rs','p = 43rs','p > 43rs','There is not enough information to compare p and 43rs.'],'D','p=43ars. The information about the roots does not constrain a relative to 1. Thus all three comparisons can occur.')
a(2,'M2H',22,62,'pct',r'The mass of A is 462% of the mass of B and 0.084% of the mass of C. If the mass of C is p% of the mass of B, what is \(\frac p{1000}\)?',None,'550','A=4.62B=0.00084C, so C/B=5500=p/100. Thus p=550000 and p/1000=550.')
# Enforce the portal's existing canonical lesson vocabulary.
canonical={'Linear equations and inequalities':'Algebraic expressions and equations','Quadratic equations and functions':'Quadratics and polynomials','Polynomials and factoring':'Quadratics and polynomials','Exponents and radicals':'Exponents, radicals and growth','Rational expressions and equations':'Algebraic expressions and equations','Absolute value':'Inequalities and absolute value','Probability':'Probability and conditional probability','Triangles and trigonometry':'Triangles and similarity','Functions':'Functions and transformations'}
trig={'P1-M1-19','P1-M2H-18','P1-M2H-21','P2-M1-18','P2-M2H-15'}
angles={'P1-M2E-02','P1-M2H-01','P2-M2H-01'}
ineq={'P1-M1-13','P1-M2E-05','P1-M2E-24','P1-M2H-12','P1-M2H-24','P2-M1-19','P2-M2E-11','P2-M2H-05'}
areas={'P1-M2E-17','P2-M2E-15'}
for r in rows:
 r['subtopic']=r['topic'];r['topic']=canonical.get(r['topic'],r['topic'])
 if r['ref'] in trig:r['topic']='Trigonometry'
 if r['ref'] in angles:r['topic']='Angles and polygons'
 if r['ref'] in ineq:r['topic']='Inequalities and absolute value'
 if r['ref'] in areas:r['topic']='Area and perimeter'
 if r['check']:assert eval(r['check']),r['ref']
assert len(rows)==142
assert len({r['ref'] for r in rows})==142
if __name__=='__main__':
 (ROOT/'transcription.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
 print('Transcribed',len(rows),'source occurrences; explicit duplicates',sum('duplicate_of' in r for r in rows))
